#include <functional>
#include <initializer_list>
#include <iterator>
#include <stdexcept>
#include <utility>
#include <vector>

#ifndef SIRKIT_HEAP_DEFINED
#define SIRKIT_HEAP_DEFINED

class Heap {
    std::vector<int> values_;

    void repair_at(std::size_t position, int value) noexcept {
        const std::size_t count = values_.size();
        for (;;) {
            const std::size_t first = position < 1 ? position * 2 + 1 : position * 4 - 1;
            if (first >= count) break;
            std::size_t child = first;
            int minimum = values_[child];
            const auto end = std::min(count, first + (position < 1 ? 2 : 4));
            for (auto probe = first + 1; probe < end; ++probe) {
                if (values_[probe] < minimum) { minimum = values_[probe]; child = probe; }
            }
            if (value <= minimum) break;
            values_[position] = minimum;
            position = child;
        }
        values_[position] = value;
    }
    void make_heap() {
        const auto count = values_.size();
        if (count < 2) return;
        for (auto position = count <= 3 ? (count - 2) / 2 : (count - 2 + 2) / 4;; --position) {
            repair_at(position, values_[position]);
            if (position == 0) break;
        }
    }
    void repair_root(int value) noexcept {
        const std::size_t count = values_.size();
        if (count == 1) { values_[0] = value; return; }
        std::size_t position;
        if (count > 2 && values_[2] < values_[1]) {
            if (value <= values_[2]) { values_[0] = value; return; }
            values_[0] = values_[2]; position = 2;
        } else {
            if (value <= values_[1]) { values_[0] = value; return; }
