variants=['baseline','a4b0','a8b0','a4b1','a4b7','a4b31'];raw=[];rng=random.Random(398193)
for compiler,native in [('gcc',False)]:
 for v in variants:
  cmd=['taskset','-c','8','/usr/bin/g++'if compiler=='gcc'else'clang++','-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS',f'-DHEADER="{p/(v+".hpp")}"',str(p/'bench.cpp'),'-o',str(p/f'{compiler}-{native}-{v}')]
  if compiler=='clang':cmd+=['--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15']
  if native:cmd+=['-march=native']
  q=subprocess.run(cmd,capture_output=True,text=True);assert q.returncode==0,q.stderr
 for n in [32,8192,262144]:
  for kind in range(5):
   for mode in range(8):
    for rep in range(3):
     order=variants+['control'];rng.shuffle(order)
     for v in order:
      src=p/(f'{compiler}-{native}-'+('baseline'if v=='control'else v))
      with (p/'run').open('wb')as f:f.write(src.read_bytes())
