      ns,checksum=map(int,q.stdout.split());raw.append(dict(compiler=compiler,native=native,n=n,kind=kind,mode=mode,rep=rep,variant=v,ns=ns,checksum=checksum))
    rows=[x for x in raw if x['compiler']==compiler and x['native']==native and x['n']==n and x['kind']==kind and x['mode']==mode];assert len({x['checksum']for x in rows})==1,(n,kind,mode)
    med={v:statistics.median(x['ns']for x in rows if x['variant']==v)for v in variants+['control']};print(compiler,native,n,kind,mode,{v:round(med[v]/med['baseline'],4)for v in med},flush=True)
    (p/'gate-raw.json').write_text(json.dumps(raw)+'\n')
summary=[]
for n in [32,8192,262144]:
 for kind in range(5):
