// clear(): 全要素を削除、容量を保持。reserve(n): n 要素分の容量を確保、再確保時 O(N)。

#include <algorithm>
#include <cstddef>
#include <functional>
#include <initializer_list>
#include <iterator>
#include <stdexcept>
#include <utility>
#include <vector>

#ifndef SIRKIT_HEAP_DEFINED
#define SIRKIT_HEAP_DEFINED

class Heap {
    std::vector<int> values_;

    void repair_quad(std::size_t position, int value) noexcept {
        const auto count = values_.size();
        while (position <= count / 4) {
            const auto first = position * 4 - 1;
            auto child = first;
            auto minimum = values_[first];
            if (first + 3 < count) {
                const auto a = values_[first], b = values_[first+1], c = values_[first+2], d = values_[first+3];
                const auto ab = std::min(a,b), cd = std::min(c,d);
                minimum = std::min(ab,cd);
                if (value <= minimum) break;
                child += ab <= cd ? (a <= b ? 0 : 1) : (c <= d ? 2 : 3);
            } else {
                for (auto probe = first + 1; probe < count; ++probe) {
                    if (values_[probe] < minimum) { minimum = values_[probe]; child = probe; }
                }
                if (value <= minimum) break;
            }
            values_[position] = minimum;
            position = child;
        }
        values_[position] = value;
    }
